function dictionaryLookup(text,from,to){const n=norm(text);const fromIndex=from==='zh-CN'?0:from==='ru'?3:2,toIndex=to==='zh-CN'?0:to==='ru'?3:2;const word=CHINESE_DICTIONARY.find(d=>norm(d[fromIndex])===n)||(from!=='ru'&&to!=='ru'?vocabulary.map(v=>[v.hanzi,v.pinyin,v.meaning]).find(d=>norm(d[fromIndex])===n):null);return word?{text:word[toIndex],pinyin:word[1],hanzi:word[0],meaning:word[2],local:true}:null;}
